import { artifact as a, creature as m, event as ev, group as g, place as p, story as s, type EntitySeed } from "../types";

export const monsters: EntitySeed[] = [
  m("typhon", "Typhon", "monster", "🌋", "Father of All Monsters", "m", { aliases: ["Typhoeus", "Typhaon", "Typhos"], summary: "The most formidable monster of Greek myth, a storm-giant with a hundred serpent heads, born to [[gaia]] and [[tartarus]] after the defeat of the Titans. He challenged [[zeus]] for rule of the cosmos and was struck down by the thunderbolt, then imprisoned in Tartarus or, in later tradition, buried beneath Mount Etna, whose eruptions were attributed to him. By [[echidna]] he fathered many of the great monsters, including Cerberus, the Hydra and the Chimera." }),
  m("echidna", "Echidna", "monster", "🐍", "Mother of All Monsters", "f", { aliases: ["Ekhidna"], summary: "A creature half fair-faced nymph and half speckled serpent, who dwelt in a cave beneath the earth. As the mate of [[typhon]] she bore many of the most famous monsters of Greek myth, among them [[cerberus]], [[orthrus]], the [[hydra|Lernaean Hydra]] and the Chimera. Her parentage varies; Hesiod's account is usually read as making her a daughter of Phorcys and Ceto." }),
  m("cerberus", "Cerberus", "monster", "🐕", "Hound of Hades", "m", { aliases: ["Kerberos"], summary: "The monstrous watchdog of the [[underworld]], offspring of [[typhon]] and [[echidna]], who fawned on the dead as they entered and devoured any who tried to leave. He is usually described with three heads, a serpent's tail and snakes along his back, though Hesiod gives him fifty heads. Capturing him and bringing him briefly to the upper world was the final labour of [[heracles]]." }),
  m("orthrus", "Orthrus", "monster", "🐕‍🦺", "Two-Headed Hound of Geryon", "m", { aliases: ["Orthus", "Orthros"], summary: "A two-headed dog, offspring of [[typhon]] and [[echidna]] and brother of [[cerberus]], who guarded the red cattle of [[geryon]] on the island of Erytheia. He was killed by [[heracles]] with his club during the tenth labour. Hesiod makes him the father of the Sphinx and the Nemean Lion." }),
  m("hydra", "Lernaean Hydra", "monster", "🐉", "Many-Headed Serpent of Lerna", "f", { aliases: ["Hydra", "Hydra of Lerna"], summary: "A many-headed water serpent, offspring of [[typhon]] and [[echidna]], that haunted the swamps of Lerna near Argos. Whenever one head was cut off two grew in its place, and one head was immortal. [[heracles]] killed it as his second labour with the help of [[iolaus]], who cauterised each neck; the hero afterwards dipped his arrows in its poisonous blood." }),
  m("chimera", "Chimera", "monster", "🔥", "Lion, Goat and Serpent", "f", { aliases: ["Chimaera", "Khimaira"], summary: "A fire-breathing monster of Lycia with the foreparts of a lion, the body of a goat and the tail of a serpent, usually counted among the offspring of [[typhon]] and [[echidna]]. She ravaged the countryside until [[bellerophon]], riding the winged horse [[pegasus]], shot her down from the air. Homer already describes her in the Iliad." }),
  m("sphinx", "Sphinx", "monster", "❓", "The Riddler of Thebes", "f", { aliases: ["Phix"], summary: "A monster with a woman's head, a lion's body and the wings of a bird, sent to plague [[thebes]]. Seated on a rock outside the city, she posed a riddle to passers-by and killed those who failed to answer. When [[oedipus]] solved it, she threw herself to her death, and he was rewarded with the Theban throne." }),
  m("nemean-lion", "Nemean Lion", "monster", "🦁", "The Invulnerable Lion", "m", { aliases: ["Lion of Nemea"], summary: "A great lion that terrorised the valley of Nemea in the Argolid, whose hide could not be pierced by any weapon. Hesiod names it a child of [[orthrus]], reared by Hera. [[heracles]] strangled it as the first of his [[twelve-labors|labours]] and thereafter wore its skin, flayed with the beast's own claws, as his characteristic cloak." }),
  m("ladon", "Ladon", "monster", "🐲", "Dragon of the Hesperides", "m", { aliases: ["Hesperian Dragon"], summary: "The serpent-dragon, in some accounts hundred-headed, that coiled around the tree of the golden apples in the [[garden-of-the-hesperides]] and never slept. Hesiod calls it a child of Phorcys and Ceto; others make it offspring of Typhon and Echidna. In the versions where [[heracles]] fetched the apples himself he killed it, and it was set among the stars as the constellation Draco." }),
  m("scylla", "Scylla", "monster", "🦑", "Six-Headed Terror of the Strait", "f", { aliases: ["Skylla"], summary: "A sea monster with six long-necked heads and twelve feet who lived in a cliffside cave opposite [[charybdis]], traditionally located at the Strait of Messina. She snatched six of the crew of [[odysseus]] as his ship passed. Later writers, notably Ovid, say she was once a beautiful nymph transformed through the jealousy of [[circe]]." }),
  m("charybdis", "Charybdis", "monster", "🌀", "The Whirlpool", "f", { aliases: ["Kharybdis"], summary: "A monstrous whirlpool lying opposite [[scylla]], which three times a day swallowed the sea and three times spewed it out again. [[odysseus]] steered clear of her on his first passage and on his second survived only by clinging to a fig tree above the vortex. The pair gave rise to the proverb of being caught between two dangers." }),
  m("medusa", "Medusa", "monster", "🐍", "The Mortal Gorgon", "f", { aliases: ["Medousa", "Gorgo"], summary: "The only mortal one of the three [[gorgons]], daughters of [[phorcys]] and [[ceto]], whose gaze turned onlookers to stone. [[perseus]] beheaded her while she slept, guided by her reflection in a polished shield, and from her neck sprang [[pegasus]] and [[chrysaor]], her children by Poseidon. In Hesiod she is a monster from birth; Ovid's later version makes her a beautiful maiden whose hair Athena turned to snakes after Poseidon violated her in the goddess's temple. Her severed head, the Gorgoneion, was set on the aegis of Athena." }),
  m("stheno", "Stheno", "monster", "🗿", "The Mighty Gorgon", "f", { aliases: ["Sthenno"], summary: "One of the two immortal [[gorgons]], daughter of [[phorcys]] and [[ceto]] and sister of [[medusa]] and Euryale. Her name means \"the mighty\". With her sister she pursued Perseus after the beheading of Medusa but could not catch him, since he wore the cap of invisibility." }),
  m("euryale", "Euryale", "monster", "🗿", "The Far-Roaming Gorgon", "f", { summary: "One of the two immortal [[gorgons]], daughter of [[phorcys]] and [[ceto]] and sister of [[medusa]] and Stheno. Pindar relates that her wailing lament for her slain sister inspired Athena to invent the music of the double pipe." }),
  m("minotaur", "Minotaur", "monster", "🐂", "Bull of Minos", "m", { aliases: ["Asterion", "Asterius", "Minotauros"], summary: "A creature with a man's body and a bull's head, born to [[pasiphae]], queen of Crete, after her union with the [[cretan-bull]]. King Minos confined him in the [[labyrinth]] built by Daedalus and fed him a regular tribute of Athenian youths and maidens. He was killed by [[theseus]], who found his way out again with the help of Ariadne's thread." }),
  m("polyphemus", "Polyphemus", "cyclops", "👁️", "The Cyclops Shepherd", "m", { aliases: ["Polyphemos"], summary: "A man-eating one-eyed giant, son of [[poseidon]] and the sea nymph Thoosa, who kept flocks on the island of the Cyclopes. In Book 9 of the Odyssey he traps [[odysseus]] and his men in his cave and devours several before the hero, calling himself \"Nobody\", gets him drunk and blinds him with a sharpened stake. His prayer to Poseidon for vengeance is the cause of Odysseus's long wanderings. Later poets tell of his unrequited love for the nymph [[galatea]]." }),
  m("brontes", "Brontes", "cyclops", "🌩️", "Thunderer", "m", { summary: "One of the three elder [[cyclopes]], sons of [[uranus]] and [[gaia]], whose name means \"thunder\". Imprisoned in Tartarus by his father and again by Cronus, he was freed by Zeus and with his brothers forged the thunderbolt in gratitude." }),
  m("steropes", "Steropes", "cyclops", "⚡", "Lightner", "m", { aliases: ["Asteropes"], summary: "One of the three elder [[cyclopes]], sons of [[uranus]] and [[gaia]], whose name means \"lightning\". Released from Tartarus by Zeus, he and his brothers Brontes and Arges forged the [[thunderbolt]] with which the Titans were overthrown." }),
  m("arges", "Arges", "cyclops", "💡", "Bright", "m", { aliases: ["Acmonides", "Pyracmon"], summary: "One of the three elder [[cyclopes]], sons of [[uranus]] and [[gaia]], whose name means \"bright\" or \"vivid flash\". With Brontes and Steropes he forged the weapons of the gods after Zeus freed them from Tartarus. One tradition holds that Apollo later killed the Cyclopes in revenge for the death of Asclepius." }),
  m("talos", "Talos", "monster", "🤖", "The Bronze Guardian of Crete", "m", { aliases: ["Talus"], summary: "A giant man of bronze, made by [[hephaestus]] or a survivor of the bronze race, who circled [[crete]] three times a day and hurled rocks at approaching ships. A single vein ran from his neck to his ankle, sealed by a bronze nail. When the Argonauts arrived, [[medea]] bewitched him and the nail was dislodged, so that his ichor drained away and he died." }),
  m("python", "Python", "monster", "🐍", "Serpent of Delphi", "x", { aliases: ["Pytho", "Delphyne"], summary: "A great serpent, child of [[gaia]], that guarded the oracle at [[delphi]] before it belonged to Apollo. The young [[apollo]] shot it dead with his arrows and took over the shrine; the Pythian Games and the title of the Pythia, his priestess, commemorated the victory. The Homeric Hymn to Apollo makes the creature a she-dragon." }),
  m("crommyonian-sow", "Crommyonian Sow", "monster", "🐖", "Terror of Crommyon", "f", { aliases: ["Phaea", "Phaia"], summary: "A savage wild sow, called Phaea after the old woman who reared her, that ravaged the district of Crommyon between Megara and Corinth. [[theseus]] killed her on his journey along the Saronic coast to Athens. Apollodorus reports that some considered her offspring of Typhon and Echidna." }),
  m("calydonian-boar", "Calydonian Boar", "monster", "🐗", "Wrath of Artemis", "m", { aliases: ["Aetolian Boar"], summary: "A monstrous boar sent by [[artemis]] to ravage the land of [[calydon]] after King Oeneus neglected her in his harvest sacrifices. The greatest heroes of the age assembled to hunt it; [[atalanta]] drew first blood and [[meleager]] delivered the killing blow. The quarrel over its hide led to Meleager's death." }),
  m("erymanthian-boar", "Erymanthian Boar", "monster", "🐗", "Quarry of the Fourth Labour", "m", { summary: "A huge wild boar that lived on Mount Erymanthus in Arcadia. As his fourth labour [[heracles]] drove it into deep snow, netted it and carried it alive to Mycenae, where the terrified [[eurystheus]] hid in a storage jar at the sight of it." }),
  m("ceryneian-hind", "Ceryneian Hind", "creature", "🦌", "The Golden-Antlered Deer", "f", { aliases: ["Cerynitian Hind", "Golden Hind"], summary: "A deer with golden antlers and bronze hooves, sacred to [[artemis]], that ranged the hills of Ceryneia in the Peloponnese. For his third labour [[heracles]] pursued it for a full year before capturing it alive. He appeased the goddess by laying the blame on Eurystheus and released the animal afterwards." }),
  m("stymphalian-birds", "Stymphalian Birds", "monster", "🐦‍⬛", "Bronze-Beaked Man-Eaters", "x", { aliases: ["Stymphalides"], summary: "A vast flock of man-eating birds with bronze beaks and, in some accounts, feathers they could shoot like arrows, which infested Lake Stymphalus in Arcadia. As his sixth labour [[heracles]] scared them into the air with bronze castanets given by Athena and shot them down. The survivors fled to an island in the Black Sea, where the Argonauts later met them." }),
  m("geryon", "Geryon", "monster", "👹", "The Three-Bodied Giant", "m", { aliases: ["Geryones", "Geryoneus"], summary: "A three-bodied, or three-headed, giant, son of [[chrysaor]] and the Oceanid Callirhoe, who lived on the island of Erytheia in the far west. He owned a famous herd of red cattle guarded by the herdsman Eurytion and the dog [[orthrus]]. [[heracles]] killed all three and drove off the cattle as his tenth labour." }),
  m("chrysaor", "Chrysaor", "monster", "⚔️", "He of the Golden Sword", "m", { aliases: ["Khrysaor"], summary: "A son of [[poseidon]] and [[medusa]] who sprang, together with the winged horse [[pegasus]], from the Gorgon's neck when Perseus beheaded her. His name means \"golden sword\". Little else is told of him beyond his fathering of the three-bodied [[geryon]] by the Oceanid Callirhoe." }),
  m("cetus", "Cetus", "monster", "🐳", "The Sea Monster of Aethiopia", "x", { aliases: ["Ketos", "Aethiopian Cetus"], summary: "The sea monster sent by [[poseidon]] to ravage Aethiopia after Queen [[cassiopeia]] boasted that she was more beautiful than the Nereids. An oracle demanded that the princess [[andromeda]] be chained to a rock as its prey. Perseus killed the beast, or turned it to stone with Medusa's head, and it was placed among the stars as the constellation Cetus." }),
  m("colchian-dragon", "Colchian Dragon", "monster", "🐉", "The Sleepless Guardian", "m", { aliases: ["Dragon of Colchis", "Drakon Kholkikos"], summary: "The enormous, never-sleeping serpent that guarded the [[golden-fleece]] in the grove of Ares in [[colchis]]. In the Argonautica [[medea]] lulls it to sleep with charms and drugs so that Jason can take the fleece; in other versions Jason kills it. A famous Attic cup shows it disgorging the hero." }),
  m("alcyoneus", "Alcyoneus", "giant", "🗻", "Eldest of the Giants", "m", { aliases: ["Alkyoneus"], summary: "One of the mightiest of the [[giants]], who could not be killed so long as he stood on the soil of his native Pallene. During the [[gigantomachy]] [[heracles]] shot him and, on Athena's advice, dragged him beyond the borders of the land, where he died." }),
  m("porphyrion", "Porphyrion", "giant", "👊", "King of the Giants", "m", { summary: "The leader of the [[giants]] in their war against the Olympians; Pindar calls him their king. In the [[gigantomachy]] he attacked Heracles and Hera, and Zeus inspired him with lust for the goddess; as he tore at her robes, Zeus struck him with a thunderbolt and Heracles finished him with an arrow." }),
  m("enceladus", "Enceladus", "giant", "🌋", "The Giant Beneath Sicily", "m", { aliases: ["Enkelados"], summary: "One of the [[giants]] who fought the gods in the [[gigantomachy]]. As he fled, [[athena]] hurled the island of Sicily upon him. Later tradition located him beneath Mount Etna and explained its eruptions and tremors as his breath and his shifting under the weight, a role he shares with Typhon." }),
  m("antaeus", "Antaeus", "giant", "🤼", "The Wrestler of Libya", "m", { aliases: ["Antaios"], summary: "A giant king of Libya, son of [[poseidon]] and [[gaia]], who forced strangers to wrestle with him and roofed his father's temple with their skulls. He drew fresh strength from every contact with the earth, his mother. [[heracles]], passing through Libya on his way to the Hesperides, defeated him by lifting him off the ground and crushing him in mid-air." }),

  m("pegasus", "Pegasus", "creature", "🦄", "The Winged Horse", "m", { aliases: ["Pegasos"], summary: "The immortal winged horse, offspring of [[poseidon]] and [[medusa]], who sprang from the Gorgon's neck when she was beheaded. [[bellerophon]] tamed him with a golden bridle given by Athena and rode him against the Chimera; when the hero tried to fly to Olympus, Pegasus threw him. The horse went on to carry the thunderbolts of Zeus, and the spring Hippocrene on Mount Helicon was said to have been struck open by his hoof." }),
  m("chiron", "Chiron", "centaur", "🏹", "Wisest of the Centaurs", "m", { aliases: ["Cheiron", "Kheiron"], summary: "The wise and just centaur, son of [[cronus]] and the Oceanid Philyra, and so of different stock from the rest of his kind. From his cave on [[mount-pelion]] he taught medicine, music, hunting and prophecy to heroes including Achilles, Jason and Asclepius. Accidentally wounded by one of Heracles' Hydra-poisoned arrows and unable to die, he gave up his immortality, in some accounts in exchange for the release of Prometheus." }),
  m("nessus", "Nessus", "centaur", "🩸", "The Treacherous Ferryman", "m", { aliases: ["Nessos"], summary: "A centaur who carried travellers across the river Evenus. When he tried to assault [[deianira]], [[heracles]] shot him with an arrow poisoned by the Hydra's blood. Dying, he persuaded Deianira to keep his blood as a love charm; years later the robe she smeared with it burned Heracles so terribly that he had himself placed on a pyre." }),
  m("arion", "Arion", "creature", "🐎", "The Immortal Horse", "m", { aliases: ["Areion"], summary: "A divinely swift, black-maned horse born to [[demeter]] after [[poseidon]] mated with her in the form of a stallion. He belonged in turn to Heracles and to Adrastus, king of Argos, whom he carried to safety as the sole surviving leader of the [[seven-against-thebes]]. Some poets credit him with the power of speech." }),
  m("phoenix", "Phoenix", "creature", "🐦‍🔥", "The Fire-Bird", "x", { aliases: ["Phoinix"], summary: "A fabulous bird of red and gold plumage, only one of which lived at a time. Herodotus reports the Egyptian tale that every five hundred years it carried its dead parent, enclosed in an egg of myrrh, to the temple of the Sun at Heliopolis. Later writers such as Ovid and Pliny add that it renews itself from its own nest of spices, and in Roman times the story of its rebirth from fire became standard." }),
  m("cretan-bull", "Cretan Bull", "creature", "🐃", "Father of the Minotaur", "m", { aliases: ["Marathonian Bull"], summary: "The magnificent bull that [[poseidon]] sent from the sea to [[minos]], who failed to sacrifice it as promised. In punishment the god made Queen Pasiphae fall in love with the animal, and she bore the [[minotaur]]. Heracles captured the bull as his seventh labour; set free, it wandered to Marathon, where Theseus finally subdued it." }),
  m("golden-ram", "Chrysomallos", "creature", "🐏", "The Flying Golden Ram", "m", { aliases: ["Golden Ram", "Chrysomallus", "Krios Khrysomallos"], summary: "A winged ram with a fleece of gold, offspring of [[poseidon]] and Theophane, sent by the cloud nymph Nephele to rescue her children Phrixus and Helle from sacrifice. Helle fell into the strait thereafter called the Hellespont, but Phrixus reached [[colchis]], sacrificed the ram and hung its [[golden-fleece|fleece]] in the grove of Ares. The ram became the constellation Aries." }),
];

export const groups: EntitySeed[] = [
  g("olympians", "The Olympians", "pantheon", "🏔️", "The Twelve Gods of Mount Olympus", undefined, { aliases: ["Twelve Olympians", "Dodekatheon", "Olympian Gods"], summary: "The principal gods of the Greek pantheon, who ruled from [[mount-olympus]] after overthrowing the [[titans]]. The canonical number was twelve: Zeus, Hera, Poseidon, Demeter, Athena, Apollo, Artemis, Ares, Aphrodite, Hephaestus, Hermes, and either Hestia or Dionysus, the list varying from place to place. Hades, though a brother of Zeus, was usually excluded because his seat was in the underworld." }),
  g("titans", "The Titans", "pantheon", "🗿", "The Elder Gods", undefined, { aliases: ["Titanes", "Titanides", "Uranides"], summary: "The generation of gods before the Olympians: the twelve children of [[uranus]] and [[gaia]], six brothers and six sisters, together with some of their descendants such as Prometheus and Atlas. Led by [[cronus]], they ruled the cosmos until Zeus and his siblings defeated them in the [[titanomachy]] and confined most of the males in Tartarus." }),
  g("muses", "The Muses", "collective", "🎨", "Nine Daughters of Memory", undefined, { aliases: ["Mousai", "Musae", "Pierides"], summary: "The nine goddesses of song, poetry and the arts, daughters of [[zeus]] and [[mnemosyne]], born in Pieria at the foot of Olympus. Poets invoked them as the source of inspiration and knowledge. In later antiquity each was assigned a province: Calliope epic, Clio history, Erato love poetry, Euterpe music, Melpomene tragedy, Polyhymnia hymns, Terpsichore dance, Thalia comedy and Urania astronomy. [[apollo]] was their leader." }),
  g("horae", "The Horae", "collective", "🌷", "The Seasons and the Hours", undefined, { aliases: ["Horai", "Hours", "Seasons"], summary: "Goddesses of the seasons and the orderly passage of time, who also guarded the gates of Olympus. Hesiod names three, daughters of [[zeus]] and [[themis]]: Eunomia (Good Order), Dike (Justice) and Eirene (Peace). At Athens they were worshipped under names reflecting growth and harvest, and later writers multiplied them into the hours of the day." }),
  g("moirai", "The Moirai", "collective", "🧵", "The Fates", undefined, { aliases: ["Fates", "Moirae", "Parcae"], summary: "The three goddesses who allotted every mortal a portion of life: [[clotho]] spun the thread, [[lachesis]] measured it and [[atropos]] cut it. Hesiod calls them daughters of Nyx in one passage and of Zeus and Themis in another. Even the gods were reluctant to overturn their decrees. The Romans identified them with the Parcae." }),
  g("charites", "The Charites", "collective", "💐", "The Graces", undefined, { aliases: ["Graces", "Gratiae", "Kharites"], summary: "Goddesses of grace, beauty, festivity and charm, usually three in number: [[aglaea]], [[euphrosyne]] and [[thalia-grace|Thalia]], daughters of Zeus and the Oceanid [[eurynome]]. They attended Aphrodite and danced with the Muses at the feasts of the gods. Their most ancient cult was at Orchomenus in Boeotia." }),
  g("erinyes", "The Erinyes", "collective", "🦇", "The Furies", undefined, { aliases: ["Furies", "Eumenides", "Dirae", "Semnai Theai"], summary: "Chthonic goddesses of vengeance who pursued those guilty of crimes against kin, above all the murder of a parent, and punished broken oaths. In Hesiod they sprang from the blood of [[uranus]] when it fell on the earth; later writers name three: Alecto, Megaera and Tisiphone. In the [[oresteia]] they hound Orestes until Athena reconciles them to Athens as the Eumenides, the Kindly Ones." }),
  g("keres", "The Keres", "collective", "🩸", "Spirits of Violent Death", undefined, { aliases: ["Ker", "Tenebrae"], summary: "Female spirits of violent and cruel death, daughters of [[nyx]], who haunted battlefields to seize the dying and drink their blood. Homer and the Hesiodic Shield of Heracles describe them with gnashing teeth, claws and bloodstained garments. They are distinct from their brother [[thanatos]], who personifies peaceful death." }),
  g("oneiroi", "The Oneiroi", "collective", "💤", "The Dreams", undefined, { aliases: ["Oneiri", "Somnia", "Dreams"], summary: "The personified spirits of dreams, children of [[nyx]] in Hesiod, who lived near the borders of the underworld. Homer describes dreams passing through two gates: true ones through the gate of horn, deceptive ones through the gate of ivory. Ovid makes them the thousand sons of [[hypnos]] and names [[morpheus]], Phobetor and Phantasos as their chiefs." }),
  g("graeae", "The Graeae", "collective", "👁️", "The Grey Sisters", undefined, { aliases: ["Graiai", "Graiae", "Grey Sisters", "Phorcides"], summary: "Sisters grey-haired from birth, daughters of [[phorcys]] and [[ceto]] and sisters of the Gorgons, who shared a single eye and a single tooth among them. Hesiod names two, Pemphredo and Enyo; later authors add Deino. [[perseus]] stole the eye as they passed it between them and returned it only when they revealed how to reach the nymphs who held the equipment he needed against Medusa." }),
  g("gorgons", "The Gorgons", "collective", "🐍", "The Snake-Haired Sisters", undefined, { aliases: ["Gorgones"], summary: "Three monstrous sisters, daughters of [[phorcys]] and [[ceto]], who lived at the western edge of the world. They are described with snakes for hair, boar's tusks, bronze hands and golden wings, and their gaze turned the beholder to stone. [[stheno]] and [[euryale]] were immortal; the third, [[medusa]], was mortal and was beheaded by Perseus." }),
  g("hesperides", "The Hesperides", "collective", "🌇", "Nymphs of the Evening", undefined, { aliases: ["Atlantides", "Western Maidens"], summary: "The clear-voiced nymphs of the evening who, with the dragon [[ladon]], tended the tree of golden apples in a [[garden-of-the-hesperides|garden]] at the western edge of the world. Hesiod makes them daughters of Nyx; others name Atlas, or Phorcys and Ceto, as their parents. Their number varies from three to seven, with Aegle, Erytheia and Hesperethusa the names most often given." }),
  g("pleiades", "The Pleiades", "collective", "✨", "Seven Starry Sisters", undefined, { aliases: ["Pleiads", "Atlantides", "Seven Sisters"], summary: "The seven daughters of the Titan [[atlas]] and the Oceanid Pleione: [[maia]], Electra, Taygete, Alcyone, Celaeno, Sterope and Merope. Several bore children to gods, Maia being the mother of Hermes. Pursued by the hunter [[orion]], they were set in the sky as a star cluster whose rising and setting marked the farming and sailing seasons." }),
  g("nereids", "The Nereids", "collective", "🧜‍♀️", "Fifty Daughters of the Sea", undefined, { aliases: ["Nereides"], summary: "The fifty sea nymphs, daughters of [[nereus]], the Old Man of the Sea, and the Oceanid Doris. They lived with their father in the depths of the Aegean and were kindly towards sailors. The best known are [[thetis]], mother of Achilles, [[amphitrite]], wife of Poseidon, and Galatea." }),
  g("oceanids", "The Oceanids", "collective", "💦", "Three Thousand Daughters of Ocean", undefined, { aliases: ["Oceanides", "Okeanides"], summary: "The nymph daughters of the Titans [[oceanus]] and [[tethys]], whom Hesiod numbers at three thousand. They presided over springs, streams, clouds and meadows, and their brothers were the river gods. Notable among them are Metis, Styx, Doris, Clymene and Eurynome; a chorus of Oceanids consoles the Titan in [[prometheus-bound]]." }),
  g("harpies", "The Harpies", "collective", "🦅", "The Snatchers", undefined, { aliases: ["Harpyiai", "Harpyiae"], summary: "Winged female spirits of sudden storm winds, whose name means \"snatchers\", daughters of Thaumas and the Oceanid Electra. Hesiod names two, Aello and Ocypete, and describes them as fair-haired; later authors add Celaeno and make them foul bird-women. They tormented the blind seer Phineus by stealing or fouling his food until the Argonauts [[zetes]] and [[calais]] drove them away." }),
  g("sirens", "The Sirens", "collective", "🎤", "Singers of the Fatal Song", undefined, { aliases: ["Seirenes", "Sirenes"], summary: "Creatures part woman and part bird whose song lured sailors to their deaths on a rocky island. They are usually called daughters of the river god [[achelous]] and one of the Muses, and number two or three. [[odysseus]] heard them safely by having himself bound to the mast while his crew rowed with wax in their ears; the Argonauts were saved when Orpheus drowned out their voices with his lyre." }),
  g("satyrs", "The Satyrs", "collective", "🍷", "Woodland Companions of Dionysus", undefined, { aliases: ["Satyroi", "Satyri", "Sileni"], summary: "Rustic male spirits of the wild who made up the retinue of [[dionysus]], given to wine, music, dancing and the pursuit of nymphs. Early Greek art shows them as men with the ears and tail of a horse; from the Hellenistic period they acquire the goat legs of [[pan]], and the Romans identified them with fauns. Older satyrs were called Sileni, and a chorus of satyrs gave its name to the satyr play." }),
  g("centaurs", "The Centaurs", "collective", "🐴", "Horse-Men of Thessaly", undefined, { aliases: ["Kentauroi", "Centauri", "Hippocentaurs"], summary: "A tribe of creatures with the torso of a man on the body of a horse, living in the mountains of Thessaly. They were descended from Ixion and the cloud Nephele, which Zeus had shaped in the likeness of Hera. Wild and lawless, they are best known for their drunken brawl with the Lapiths at the wedding of [[pirithous]], the Centauromachy. The learned [[chiron]] and the hospitable Pholus were exceptions." }),
  g("cyclopes", "The Cyclopes", "collective", "👁️", "The One-Eyed Giants", undefined, { aliases: ["Kyklopes", "Cyclops"], summary: "One-eyed giants of two distinct kinds. In Hesiod they are three sons of [[uranus]] and [[gaia]], named [[brontes]], [[steropes]] and [[arges]], master smiths who forged the thunderbolt of Zeus, the trident of Poseidon and the helm of Hades. In the Odyssey they are a lawless race of cave-dwelling shepherds, among them Polyphemus. A third tradition credits Cyclopes with building the massive walls of Mycenae and Tiryns." }),
  g("hecatoncheires", "The Hecatoncheires", "collective", "🙌", "The Hundred-Handed Ones", undefined, { aliases: ["Hundred-Handers", "Hekatonkheires", "Centimani"], summary: "Three giants of immense strength, each with a hundred arms and fifty heads, sons of [[uranus]] and [[gaia]]: Briareus (also called Aegaeon), Cottus and Gyges. Their father, and afterwards Cronus, kept them imprisoned in Tartarus. Freed by [[zeus]], they turned the tide of the [[titanomachy]] by hurling volleys of boulders and afterwards served as warders of the defeated Titans." }),
  g("giants", "The Gigantes", "collective", "🗻", "Earth-Born Giants", undefined, { aliases: ["Giants", "Gegeneis"], summary: "A race of huge and mighty warriors born to [[gaia]] from the blood of the castrated [[uranus]]. At their mother's urging they made war on the Olympians in the [[gigantomachy]] and were destroyed with the help of Heracles. Early art shows them as armoured hoplites; later they are given serpents for legs. Porphyrion, Alcyoneus and Enceladus are the best known." }),
  g("amazons", "The Amazons", "faction", "🏹", "Warrior Women of the East", undefined, { aliases: ["Amazones"], summary: "A nation of warrior women, daughters of [[ares]], usually located at Themiscyra on the river Thermodon on the southern shore of the Black Sea. Heracles fought them for the belt of their queen [[hippolyta]], Theseus carried off one of them and repelled their invasion of Attica, and [[penthesilea]] led them to Troy, where she fell to Achilles. Battles with Amazons were a favourite subject of Greek art." }),
  g("maenads", "The Maenads", "collective", "🌿", "Frenzied Followers of Dionysus", undefined, { aliases: ["Bacchae", "Bacchantes", "Mainades", "Thyiades"], summary: "The female devotees of [[dionysus]], whose name means \"raving ones\". Possessed by the god, they roamed the mountains dressed in fawnskins, carrying the ivy-tipped thyrsus, and in their ecstasy were said to tear animals apart with their bare hands. In myth they dismember [[pentheus]], as dramatised in the [[bacchae]], and in some accounts Orpheus." }),
  g("argonauts", "The Argonauts", "faction", "⛵", "Crew of the Argo", undefined, { aliases: ["Argonautai", "Minyans"], summary: "The band of about fifty heroes who sailed with [[jason]] aboard the [[argo]] to bring the Golden Fleece back from Colchis, a generation before the Trojan War. Lists of the crew vary, but regularly include Heracles, Orpheus, Castor and Pollux, Peleus, Telamon, the sons of Boreas and the helmsman Tiphys. The fullest surviving account is the [[argonautica]] of Apollonius of Rhodes." }),
  g("achaeans", "The Achaeans", "faction", "🏺", "The Greek Coalition at Troy", undefined, { aliases: ["Achaioi", "Argives", "Danaans"], summary: "Homer's usual collective name, alongside Argives and Danaans, for the Greeks who fought in the [[trojan-war]]. The coalition was commanded by [[agamemnon]] of Mycenae and drew contingents from across the Greek world, listed in the Catalogue of Ships in Book 2 of the Iliad. Its foremost warriors included Achilles, the two Ajaxes, Diomedes, Odysseus, Nestor and Menelaus." }),
  g("trojans", "The Trojans", "faction", "🏰", "Defenders of Troy and Their Allies", undefined, { aliases: ["Troes", "Teucrians", "Dardanians"], summary: "The people of [[troy]] and the allied contingents who defended the city in the Trojan War. They were ruled by King [[priam]] and led in the field by his son [[hector]]; their allies included Lycians under Sarpedon and Glaucus, Dardanians under Aeneas, Thracians, and late arrivals such as the Amazons and Memnon's Aethiopians. Homer portrays them with notable sympathy." }),
  g("judges-of-the-dead", "Judges of the Dead", "collective", "⚖️", "Arbiters of the Underworld", undefined, { aliases: ["Judges of the Underworld"], summary: "The three mortal sons of Zeus appointed after death to judge the shades in the [[underworld]] as a reward for their justice in life: [[minos]], [[rhadamanthus]] and [[aeacus]]. In Plato's Gorgias, Rhadamanthus judges the souls from Asia and Aeacus those from Europe, with Minos holding the deciding vote. Some accounts add Triptolemus." }),
];

export const places: EntitySeed[] = [
  p("mount-olympus", "Mount Olympus", "mountain", "🏔️", "Home of the Gods", undefined, { aliases: ["Olympos", "Olympus"], summary: "The highest mountain in Greece, on the border of Thessaly and Macedonia, regarded as the seat of the [[olympians]]. On its summit, above the clouds, stood the palace of [[zeus]] and the halls built for the other gods by Hephaestus, where they feasted on nectar and ambrosia. Its gates of cloud were kept by the Horae." }),
  p("underworld", "The Underworld", "realm", "🕯️", "House of Hades", undefined, { aliases: ["Hades", "House of Hades", "Erebus"], summary: "The subterranean realm of the dead, ruled by [[hades]] and [[persephone]]. The shades were escorted there by Hermes and ferried across the Styx or Acheron by [[charon]], past the watchdog [[cerberus]]. Its regions came to include the Asphodel Meadows for the ordinary dead, Elysium for the blessed and Tartarus for the damned. A few living heroes made the descent, among them Heracles, Orpheus, Theseus, Odysseus and Aeneas." }),
  p("elysium", "Elysium", "realm", "🌼", "The Blessed Fields", undefined, { aliases: ["Elysian Fields", "Elysian Plain", "Isles of the Blessed"], summary: "The paradise reserved for heroes and the virtuous dead. Homer places the Elysian Plain at the western ends of the earth, by the stream of Oceanus, where [[rhadamanthus]] dwells and there is neither snow nor storm. Hesiod and Pindar speak instead of the Isles of the Blessed, ruled by Cronus; later authors, including Virgil, make Elysium a region of the underworld." }),
  p("troy", "Troy", "city", "🏰", "The Well-Walled City", undefined, { aliases: ["Ilium", "Ilion", "Ilios", "Troia"], summary: "A wealthy fortified city in the north-west of Asia Minor, near the Hellespont, and the setting of the [[trojan-war]]. Its royal line descended from Dardanus, a son of Zeus, and its walls were built by Poseidon and Apollo for King Laomedon. Under [[priam]] it withstood a ten-year siege by the Achaeans before falling to the stratagem of the wooden horse. The site is identified with the mound of Hisarlik in modern Turkey, excavated by Heinrich Schliemann from 1870." }),
  p("colchis", "Colchis", "kingdom", "🐏", "Land of the Golden Fleece", undefined, { aliases: ["Kolkhis", "Aea"], summary: "A kingdom at the eastern end of the Black Sea, in what is now western Georgia, regarded by the Greeks as the edge of the known world. It was ruled by [[aeetes]], son of Helios, and was the home of his daughter [[medea]]. The [[golden-fleece]] hung there in a grove of Ares, making it the destination of the Argonauts." }),
  p("crete", "Crete", "island", "🐂", "Island of Minos", undefined, { aliases: ["Krete", "Creta"], summary: "The largest of the Greek islands and the seat of King [[minos]], who ruled the seas from his palace at Knossos. The infant [[zeus]] was hidden from Cronus in a cave on Mount Dicte or Mount Ida, and Zeus later carried Europa to the island in the form of a bull. It is also the setting for the stories of Pasiphae, the Minotaur, Daedalus and the bronze giant Talos." }),
  p("labyrinth", "The Labyrinth", "structure", "🌀", "Maze of the Minotaur", undefined, { aliases: ["Labyrinthos", "Cretan Labyrinth"], summary: "The vast maze built at Knossos by [[daedalus]] on the orders of King Minos to conceal the [[minotaur]]. Its passages were so intricate that no one who entered could find the way out. [[theseus]] escaped after killing the monster by following a thread given to him by Ariadne; Daedalus himself was later imprisoned there with his son Icarus." }),
  p("thebes", "Thebes", "city", "🐉", "The Seven-Gated City", undefined, { aliases: ["Thebai", "Cadmeia"], summary: "The chief city of Boeotia, founded by [[cadmus]], who sowed the teeth of a dragon he had killed there and raised a crop of armed men, the Spartoi. Its walls were built by Amphion and Zethus to the music of a lyre. Thebes was the birthplace of Dionysus and Heracles and the stage for the tragic history of [[oedipus]] and his children, including the war of the [[seven-against-thebes]]." }),
  p("athens", "Athens", "city", "🫒", "City of Athena", undefined, { aliases: ["Athenai", "Athenae"], summary: "The chief city of Attica, named for its patron [[athena]], who won it in a contest with Poseidon by producing the first olive tree on the Acropolis. Its early kings, Cecrops and Erechtheus, were said to be born from the earth itself. Its greatest hero was [[theseus]], credited with uniting Attica and freeing the city from its tribute to Minos." }),
  p("sparta", "Sparta", "city", "🛡️", "Home of Helen and Menelaus", undefined, { aliases: ["Lacedaemon", "Lakedaimon"], summary: "The chief city of Laconia in the southern Peloponnese, also called Lacedaemon. In myth it was ruled by [[tyndareus]], husband of Leda, and afterwards by his son-in-law [[menelaus]]. It was from the Spartan palace that Paris carried off [[helen]], and it was the home of her brothers, the Dioscuri." }),
  p("mycenae", "Mycenae", "city", "🦁", "Rich in Gold", undefined, { aliases: ["Mykenai", "Mykene"], summary: "A citadel in the Argolid, said to have been founded by [[perseus]] and fortified with walls raised by the Cyclopes. It was the seat of Eurystheus and later of the house of Atreus, including [[agamemnon]], who was murdered there on his return from Troy. Homer calls it \"rich in gold\", an epithet borne out by the Bronze Age shaft graves excavated on the site." }),
  p("argos", "Argos", "city", "🐎", "City Sacred to Hera", undefined, { aliases: ["Argos Hippobotos"], summary: "An ancient city of the Argolid in the north-eastern Peloponnese, sacred above all to [[hera]], whose great sanctuary, the Heraion, stood nearby. Its mythical history includes the river god Inachus and his daughter Io, Danaus and his fifty daughters, Acrisius and Danae, and Adrastus, who led the Seven against Thebes. At Troy its men were commanded by [[diomedes]]." }),
  p("corinth", "Corinth", "city", "🏛️", "City of the Isthmus", undefined, { aliases: ["Korinthos", "Ephyra"], summary: "A wealthy city commanding the isthmus that joins the Peloponnese to central Greece, known in early myth as Ephyra. It was founded or ruled by the cunning [[sisyphus]]; his grandson [[bellerophon]] tamed Pegasus beside its spring, Peirene. Oedipus was brought up at the Corinthian court, and it is the setting of Euripides' [[medea-play|Medea]]." }),
  p("ithaca", "Ithaca", "island", "🏝️", "Home of Odysseus", undefined, { aliases: ["Ithaka", "Ithake"], summary: "A small, rugged island in the Ionian Sea off the west coast of Greece, the kingdom of [[odysseus]]. During his twenty-year absence his wife [[penelope]] and son Telemachus held out there against a crowd of suitors occupying the palace. It is the goal of the hero's journey throughout the [[odyssey]]." }),
  p("delphi", "Delphi", "sanctuary", "🔮", "Navel of the World", undefined, { aliases: ["Pytho", "Delphoi"], summary: "The sanctuary of [[apollo]] on the slopes of Mount Parnassus and the seat of the most authoritative oracle in the Greek world. The god took possession of it by killing the serpent [[python]]; his priestess, the Pythia, delivered his responses. Delphi was held to be the centre of the earth, marked by the omphalos stone where two eagles released by Zeus had met." }),
  p("delos", "Delos", "island", "🌴", "Birthplace of Apollo and Artemis", undefined, { aliases: ["Ortygia", "Asteria"], summary: "A tiny island at the centre of the Cyclades, sacred as the birthplace of [[apollo]] and, in most accounts, [[artemis]]. Because Hera had forbidden any land to shelter the pregnant [[leto]], only this floating island would receive her, and it was afterwards anchored to the sea floor. It became one of the chief sanctuaries of Apollo." }),
  p("iolcus", "Iolcus", "city", "⚓", "Home Port of the Argo", undefined, { aliases: ["Iolkos", "Iolcos"], summary: "A city of Thessaly on the Gulf of Pagasae, at the foot of Mount Pelion. Its throne was seized by [[pelias]] from his half-brother Aeson, whose son [[jason]] was sent to fetch the Golden Fleece as the price of his inheritance. The Argo was built and launched from its harbour, and Pelias met his death there through the wiles of Medea." }),
  p("calydon", "Calydon", "city", "🐗", "Site of the Great Boar Hunt", undefined, { aliases: ["Kalydon"], summary: "A city of Aetolia in western Greece, ruled by King Oeneus, who received the vine from Dionysus. When Oeneus forgot Artemis in his offerings, she sent the [[calydonian-boar]] to devastate the land, occasioning the famous hunt. It was the home of [[meleager]], of Deianira and of Tydeus, father of Diomedes." }),
  p("ogygia", "Ogygia", "island", "🏝️", "Calypso's Island", undefined, { aliases: ["Ogygie"], summary: "The remote, wooded island, called by Homer the navel of the sea, where the nymph [[calypso]] lived. [[odysseus]] was washed ashore there after losing his last ship and was kept for seven years until the gods sent Hermes to order his release. Ancient writers variously located it near Malta or in the far western ocean." }),
  p("aeaea", "Aeaea", "island", "🐖", "Circe's Island", undefined, { aliases: ["Aiaia", "Aiaie"], summary: "The island home of the sorceress [[circe]], daughter of Helios. There she turned half the crew of [[odysseus]] into swine until the hero, protected by the herb moly, compelled her to restore them; he then stayed a year as her guest. Homer places it in the far east, by the rising sun, but Roman tradition identified it with Monte Circeo on the coast of Latium." }),
  p("mount-pelion", "Mount Pelion", "mountain", "🌲", "Mountain of the Centaurs", undefined, { aliases: ["Pelium", "Pilio"], summary: "A forested mountain on the coast of Thessaly, the haunt of the centaurs and the site of the cave where [[chiron]] reared and taught Achilles, Jason and other heroes. The wedding of Peleus and Thetis was celebrated there, and its pines supplied the timber for the Argo. The giants Otus and Ephialtes tried to pile Pelion on Mount Ossa to storm heaven." }),
  p("caucasus", "The Caucasus", "mountain", "⛓️", "Where Prometheus Was Chained", undefined, { aliases: ["Kaukasos", "Mount Caucasus"], summary: "The mountain range between the Black Sea and the Caspian, which the Greeks regarded as one of the boundaries of the world. Zeus had [[prometheus]] chained to one of its peaks for stealing fire, and each day an eagle came to feed on his liver, which grew back overnight. [[heracles]] eventually shot the eagle and set the Titan free." }),
  p("garden-of-the-hesperides", "Garden of the Hesperides", "garden", "🍎", "Orchard at the Edge of the World", undefined, { aliases: ["Garden of Hera", "Orchard of the Hesperides"], summary: "A sacred orchard in the far west, near the place where [[atlas]] holds up the sky, in which grew the tree of [[golden-apples|golden apples]] that Gaia gave to Hera as a wedding gift. It was tended by the [[hesperides]] and guarded by the dragon Ladon. Fetching its apples was the eleventh labour of Heracles." }),
];

export const events: EntitySeed[] = [
  ev("castration-of-uranus", "Castration of Uranus", "succession", "🌙", "Overthrow of the Sky by Cronus", undefined, { aliases: ["Overthrow of Uranus"], summary: "The first succession in the divine order, told in Hesiod's [[theogony]]. Because [[uranus]] kept his children confined within [[gaia]], she made an adamantine sickle and urged her sons to act; [[cronus]] alone agreed, ambushed his father and castrated him. From the blood that fell on the earth came the Erinyes, the Giants and the Meliae, and from the severed parts cast into the sea arose Aphrodite." }),
  ev("titanomachy", "Titanomachy", "war", "⚡", "The Ten-Year War of Gods and Titans", undefined, { aliases: ["War of the Titans", "Titanomachia"], summary: "The ten-year war in which [[zeus]] and his siblings, based on Olympus, overthrew the [[titans]] led by [[cronus]], who fought from Mount Othrys. It was decided when Zeus freed the Cyclopes, who armed him with the thunderbolt, and the Hundred-Handers, who overwhelmed the Titans with boulders. The defeated were imprisoned in Tartarus and Atlas was condemned to bear the sky. Hesiod's Theogony is the main source; an early epic on the subject is lost." }),
  ev("typhonomachy", "Typhonomachy", "war", "🌋", "Battle of Zeus and Typhon", undefined, { aliases: ["Typhonomachia", "Battle of Zeus and Typhon"], summary: "The last great challenge to the rule of [[zeus]], in which [[typhon]], the monstrous son of Gaia and Tartarus, attacked heaven. In Hesiod, Zeus blasts him with thunderbolts and hurls him into Tartarus. Apollodorus gives a longer version in which Typhon first cuts out the sinews of Zeus, which Hermes recovers, before the god pursues him across the world and buries him under Mount Etna." }),
  ev("gigantomachy", "Gigantomachy", "war", "🗻", "The War Against the Giants", undefined, { aliases: ["War of the Giants", "Gigantomachia"], summary: "The battle between the Olympian gods and the [[giants]], sons of Gaia, fought at Phlegra or Pallene. An oracle declared that the Giants could be killed only with the aid of a mortal, so the gods enlisted [[heracles]], who finished off each opponent with his arrows. The fullest account is in Apollodorus. The subject was immensely popular in art, notably on the Parthenon metopes and the Great Altar of Pergamon." }),
  ev("theft-of-fire", "Theft of Fire", "myth", "🔥", "Prometheus's Gift to Mankind", undefined, { aliases: ["Theft of Fire by Prometheus"], summary: "After [[prometheus]] tricked [[zeus]] over the division of sacrificial meat at Mecone, the god withheld fire from mortals. Prometheus stole it back, hidden in the hollow stalk of a fennel plant. In retaliation Zeus had the first woman, [[pandora]], fashioned as a bane for men and had Prometheus chained in the Caucasus with an eagle devouring his liver. The story is told in Hesiod's Theogony and Works and Days." }),
  ev("birth-of-athena", "Birth of Athena", "myth", "🪓", "Born From the Head of Zeus", undefined, { summary: "Warned that a son born to his first wife [[metis]] would overthrow him, [[zeus]] swallowed her while she was pregnant. In time he was seized by a violent headache, and when Hephaestus, or in some versions Prometheus, split his skull with an axe, [[athena]] sprang out fully grown and armed, uttering a war cry. The birth was depicted on the east pediment of the Parthenon." }),
  ev("abduction-of-persephone", "Abduction of Persephone", "myth", "🌸", "Origin of the Seasons", undefined, { aliases: ["Rape of Persephone", "Rape of Proserpina"], summary: "With the consent of Zeus, [[hades]] seized [[persephone]] as she gathered flowers and carried her down to be his queen. Her mother [[demeter]] searched the earth and in her grief let no crops grow, until Zeus ordered the girl's return. Because she had eaten pomegranate seeds in the underworld, she must spend part of each year there. The Homeric Hymn to Demeter is the chief source, and the story was the foundation myth of the Eleusinian Mysteries." }),
  ev("slaying-of-medusa", "Slaying of Medusa", "quest", "🪞", "Perseus's Quest", undefined, { aliases: ["Quest of Perseus"], summary: "Sent by King [[polydectes]] of Seriphos to fetch the Gorgon's head, [[perseus]] was helped by Athena and Hermes. He forced the Graeae to direct him to the nymphs who supplied winged sandals, the cap of invisibility and a pouch. He then beheaded the sleeping [[medusa]] while watching her reflection in his shield. On the way home he rescued Andromeda and finally used the head to turn Polydectes to stone." }),
  ev("twelve-labors", "Twelve Labours of Heracles", "quest", "🦁", "The Penance of Heracles", undefined, { aliases: ["Twelve Labors", "Labours of Hercules", "Dodekathlon"], summary: "The tasks that [[heracles]] performed over twelve years for King [[eurystheus]] of Tiryns and Mycenae, imposed by the Delphic oracle as atonement for killing his children in a madness sent by Hera. In the canonical order they are: the Nemean Lion, the Lernaean Hydra, the Ceryneian Hind, the Erymanthian Boar, the stables of Augeas, the Stymphalian Birds, the Cretan Bull, the mares of Diomedes, the belt of Hippolyta, the cattle of Geryon, the apples of the Hesperides and the capture of Cerberus." }),
  ev("slaying-of-the-minotaur", "Slaying of the Minotaur", "quest", "🧶", "Theseus in the Labyrinth", undefined, { aliases: ["Theseus and the Minotaur"], summary: "To end the tribute of seven youths and seven maidens that Athens owed to Minos, [[theseus]] sailed to Crete as one of the victims. [[ariadne]], the king's daughter, fell in love with him and gave him a ball of thread by which he retraced his path through the Labyrinth after killing the [[minotaur]]. He abandoned Ariadne on Naxos, and his failure to change his black sail for a white one drove his father Aegeus to suicide." }),
  ev("calydonian-boar-hunt", "Calydonian Boar Hunt", "quest", "🐗", "Gathering of Heroes in Aetolia", undefined, { aliases: ["Hunt of the Calydonian Boar"], summary: "The hunt for the [[calydonian-boar]], to which [[meleager]] summoned heroes from across Greece, among them Theseus, Jason, the Dioscuri, Peleus and the huntress [[atalanta]]. Atalanta wounded the beast first and Meleager killed it, then awarded her the hide. When his uncles objected he killed them, and his mother Althaea burned the brand on which his life depended. The story is told in the Iliad and by Ovid." }),
  ev("voyage-of-the-argonauts", "Voyage of the Argonauts", "quest", "⛵", "The Quest for the Golden Fleece", undefined, { aliases: ["Quest for the Golden Fleece", "Argonautic Expedition"], summary: "The expedition of [[jason]] and the [[argonauts]] from Iolcus to Colchis to recover the Golden Fleece for King Pelias. On the way they visited Lemnos, lost Hylas and Heracles in Mysia, rescued Phineus from the Harpies and passed the Clashing Rocks. In Colchis [[medea]] helped Jason yoke fire-breathing bulls, defeat the earth-born warriors and take the fleece. The principal source is the Argonautica of Apollonius of Rhodes." }),
  ev("seven-against-thebes", "Seven Against Thebes", "war", "🚪", "War of the Sons of Oedipus", undefined, { aliases: ["War of the Seven", "Theban War"], summary: "The war that arose when Eteocles refused to yield the throne of [[thebes]] to his brother Polynices as agreed. Polynices and his father-in-law Adrastus of Argos led seven champions against the city's seven gates. All the attackers but Adrastus died, and the two sons of [[oedipus]] killed each other in single combat. Aeschylus dramatised the conflict, and its aftermath is the subject of Sophocles' Antigone. A generation later the Epigoni, sons of the Seven, took the city." }),
  ev("wedding-of-peleus-and-thetis", "Wedding of Peleus and Thetis", "myth", "💒", "The Feast Where Discord Struck", undefined, { aliases: ["Marriage of Peleus and Thetis"], summary: "Because the sea goddess [[thetis]] was fated to bear a son greater than his father, Zeus had her married to the mortal [[peleus]]. All the gods attended the feast on Mount Pelion except [[eris]], who was not invited. She threw among the guests a golden apple marked for the fairest, setting Hera, Athena and Aphrodite at odds and leading to the Judgement of Paris. The child of the marriage was Achilles." }),
  ev("judgement-of-paris", "Judgement of Paris", "myth", "🍏", "Origin of the Trojan War", undefined, { aliases: ["Judgment of Paris"], summary: "The contest in which Hera, Athena and Aphrodite each claimed the [[apple-of-discord]] as the fairest. Zeus referred the decision to the Trojan prince [[paris]], then herding flocks on Mount Ida. Hera offered him kingship, Athena victory in war and [[aphrodite]] the most beautiful woman in the world; he chose Aphrodite. His prize was Helen, and her abduction from Sparta caused the Trojan War. The story was told in the lost epic Cypria." }),
  ev("trojan-war", "Trojan War", "war", "🏹", "Ten Years Before the Walls of Troy", undefined, { aliases: ["War of Troy", "Siege of Troy"], summary: "The ten-year siege of [[troy]] by a Greek coalition under [[agamemnon]], undertaken to recover [[helen]], wife of Menelaus of Sparta, whom the Trojan prince Paris had carried off. The fighting claimed the greatest heroes of both armies, including Patroclus, Hector and Achilles, and ended with the stratagem of the wooden horse and the sack of the city. The Iliad covers only a few weeks of the final year; the rest was told in the poems of the Epic Cycle. Ancient chronographers dated the war to around 1200 BC." }),
  ev("fall-of-troy", "Fall of Troy", "war", "🐴", "The Sack of the City", undefined, { aliases: ["Sack of Troy", "Iliupersis"], summary: "The capture and destruction of Troy in the tenth year of the war. The Greeks pretended to sail away, leaving the [[trojan-horse]] filled with armed men; despite the warnings of Cassandra and Laocoon the Trojans brought it inside the walls. That night the city was sacked: Neoptolemus killed [[priam]] at the altar of Zeus, Astyanax was thrown from the walls and the women were enslaved. [[aeneas]] escaped with his father and son. The fullest account is Book 2 of the Aeneid." }),
  ev("return-of-odysseus", "Return of Odysseus", "quest", "🧭", "The Ten-Year Voyage Home", undefined, { aliases: ["Nostos of Odysseus", "Wanderings of Odysseus"], summary: "The ten-year homeward journey of [[odysseus]] from Troy to Ithaca, prolonged by the anger of Poseidon over the blinding of Polyphemus. Its episodes include the Lotus-Eaters, the Cyclops, Circe, a visit to the land of the dead, the Sirens, Scylla and Charybdis, and seven years with Calypso. Reaching home alone and disguised as a beggar, he killed the suitors besieging [[penelope]] and reclaimed his kingdom. It is the subject of the [[odyssey]]." }),
];

export const artifacts: EntitySeed[] = [
  a("thunderbolt", "Thunderbolt of Zeus", "weapon", "⚡", "Forged by the Cyclopes", undefined, { aliases: ["Keraunos", "Thunderbolt"], summary: "The weapon and chief attribute of [[zeus]], a bolt of lightning forged for him by the [[cyclopes]] in gratitude for their release from Tartarus. With it he defeated the Titans, Typhon and the Giants, and punished mortals such as Salmoneus, Capaneus and Asclepius. In art it appears as a double-ended bundle of flames, sometimes winged." }),
  a("trident", "Trident of Poseidon", "weapon", "🔱", "Shaker of Earth and Sea", undefined, { aliases: ["Triaina"], summary: "The three-pronged spear of [[poseidon]], made by the [[cyclopes]] during the war with the Titans. With it the god stirred up and calmed the sea, split rocks and caused earthquakes. A blow of the trident on the Athenian Acropolis produced the salt spring he offered the city in his contest with Athena." }),
  a("helm-of-darkness", "Helm of Darkness", "armor", "🪖", "Cap of Invisibility", undefined, { aliases: ["Cap of Hades", "Cap of Invisibility", "Aidos Kynee"], summary: "A cap, made by the [[cyclopes]] for [[hades]] at the time of the Titanomachy, that rendered its wearer invisible. It was lent to other gods and heroes: Athena wears it in the Iliad to hide from Ares, Hermes in the battle with the Giants, and [[perseus]] used it to escape the sisters of Medusa." }),
  a("aegis", "The Aegis", "armor", "🛡️", "The Terrible Goatskin Shield", undefined, { aliases: ["Aigis"], summary: "A divine shield or fringed goatskin cloak carried by [[zeus]] and, more often, by [[athena]], which spread panic among enemies when shaken. Homer describes it as ageless, hung with a hundred golden tassels. In art Athena wears it over her breast, edged with snakes and bearing the head of the Gorgon. Some accounts say it was made from the hide of the goat [[amalthea]]." }),
  a("caduceus", "Caduceus", "staff", "⚕️", "Herald's Staff of Hermes", undefined, { aliases: ["Kerykeion"], summary: "The herald's wand of [[hermes]], a staff entwined by two serpents and often topped with wings, given to him by Apollo in exchange for the lyre. With it he lulled mortals to sleep or woke them and guided the souls of the dead. It is often confused with the single-snake rod of [[asclepius]], the proper emblem of medicine." }),
  a("winged-sandals", "Winged Sandals", "gear", "👟", "Talaria of Hermes", undefined, { aliases: ["Talaria", "Pedila"], summary: "The golden, winged sandals of [[hermes]], which carried him over land and sea as swiftly as the wind. Homer calls them immortal and golden; the wings are a later addition of poets and artists. A pair was lent to [[perseus]], through the nymphs or Hermes himself, for his expedition against Medusa." }),
  a("adamantine-sickle", "Adamantine Sickle", "weapon", "🌙", "The Harpe", undefined, { aliases: ["Harpe", "Sickle of Cronus"], summary: "The jagged-toothed sickle of grey adamant that [[gaia]] made and gave to [[cronus]], who used it to castrate his father [[uranus]]. A similar curved blade, the harpe, was given by Hermes to Perseus for beheading Medusa, and in Apollodorus Zeus wields one against Typhon." }),
  a("golden-fleece", "Golden Fleece", "treasure", "🐑", "Fleece of the Flying Ram", undefined, { aliases: ["Chrysomallon Deras"], summary: "The fleece of the winged [[golden-ram|golden ram]] that carried Phrixus to Colchis. Phrixus sacrificed the ram and gave its fleece to King Aeetes, who hung it on an oak in the grove of Ares under the guard of a sleepless dragon. Its recovery was the task set for [[jason]] by Pelias and the object of the voyage of the Argonauts." }),
  a("argo", "The Argo", "ship", "⛵", "Ship of the Argonauts", undefined, { aliases: ["Argo Navis"], summary: "The fifty-oared ship that carried [[jason]] and the Argonauts to Colchis, built by the shipwright [[argus]] with the help of Athena. Into its prow the goddess fitted a beam from the sacred oak of Dodona, which had the power of speech and prophecy. After the voyage the ship was dedicated to Poseidon at the Isthmus and placed among the stars." }),
  a("armor-of-achilles", "Armor of Achilles", "armor", "🛡️", "Forged by Hephaestus", undefined, { aliases: ["Arms of Achilles", "Shield of Achilles"], summary: "The divine armour that [[hephaestus]] made at the request of Thetis after Hector stripped Achilles' first set from the body of Patroclus. Its great shield, decorated with scenes of the earth, heavens, and cities at peace and war, is described at length in Book 18 of the [[iliad]]. After the death of [[achilles]] the arms were awarded to Odysseus rather than Ajax, who killed himself over the slight." }),
  a("apple-of-discord", "Apple of Discord", "treasure", "🍎", "Inscribed: 'To the Fairest'", undefined, { aliases: ["Golden Apple of Eris", "Apple of Eris"], summary: "The golden apple that [[eris]], goddess of strife, threw among the guests at the wedding of Peleus and Thetis, to which she had not been invited. Marked as a prize for the fairest, it was claimed by Hera, Athena and Aphrodite. The dispute was settled by the [[judgement-of-paris]] and led ultimately to the Trojan War." }),
  a("pandoras-jar", "Pandora's Jar", "vessel", "🏺", "Vessel of the World's Evils", undefined, { aliases: ["Pandora's Box", "Pithos of Pandora"], summary: "The large storage jar (pithos) that [[pandora]], the first woman, opened, releasing toil, sickness and all other evils among mankind; only Hope remained inside beneath the rim when she replaced the lid. The story is told in Hesiod's Works and Days. The familiar \"box\" derives from a sixteenth-century mistranslation by Erasmus, who rendered pithos as pyxis." }),
  a("trojan-horse", "Trojan Horse", "structure", "🐴", "Stratagem That Ended the Trojan War", undefined, { aliases: ["Wooden Horse", "Doureios Hippos"], summary: "The huge hollow wooden horse built by Epeius with the aid of Athena, on a plan usually credited to [[odysseus]]. The Greeks hid picked warriors inside, feigned departure and left the horse as a supposed offering to Athena. Persuaded by the false deserter Sinon, the Trojans dragged it into the city, and at night the men emerged and opened the gates. The tale is sketched in the Odyssey and told fully in Book 2 of the [[aeneid]]." }),
  a("bow-of-heracles", "Bow of Heracles", "weapon", "🏹", "With Hydra-Poisoned Arrows", undefined, { aliases: ["Bow of Hercules", "Bow of Philoctetes"], summary: "The bow of [[heracles]], whose arrows had been dipped in the venom of the Lernaean Hydra and inflicted incurable wounds. On his pyre Heracles gave it to [[philoctetes]], or his father Poeas, for lighting the fire. A prophecy declared that Troy could not fall without it, so the Greeks fetched Philoctetes from Lemnos, and with it he killed Paris." }),
  a("lyre-of-orpheus", "Lyre of Orpheus", "instrument", "🎻", "Charmer of Beasts, Trees and Stones", undefined, { aliases: ["Lyra"], summary: "The lyre played by [[orpheus]], in most accounts a gift from Apollo. Its music charmed wild animals, trees and rocks, drowned out the song of the Sirens for the Argonauts and moved Hades and Persephone to release Eurydice. After the death of Orpheus the Muses, or Zeus, placed it in the sky as the constellation Lyra." }),
  a("ariadnes-thread", "Ariadne's Thread", "gear", "🧵", "Guide Through the Labyrinth", undefined, { aliases: ["Clew of Ariadne"], summary: "The ball of thread that [[ariadne]], on the advice of Daedalus, gave to [[theseus]] before he entered the [[labyrinth]]. By tying one end to the entrance and unwinding it as he went, he was able to retrace his steps after killing the Minotaur. The English word \"clue\" descends from \"clew\", a ball of thread, by way of this story." }),
  a("necklace-of-harmonia", "Necklace of Harmonia", "treasure", "📿", "Cursed Heirloom of Thebes", undefined, { aliases: ["Necklace of Eriphyle"], summary: "A golden necklace made by [[hephaestus]] and given to [[harmonia]] at her wedding to Cadmus, which brought misfortune on all who owned it. It passed down the Theban royal house to Jocasta and then Polynices, who used it to bribe Eriphyle into sending her husband Amphiaraus to his death with the Seven against Thebes. It was finally dedicated at Delphi." }),
  a("golden-apples", "Golden Apples of the Hesperides", "treasure", "🍏", "Hera's Wedding Present", undefined, { aliases: ["Apples of the Hesperides"], summary: "The fruit of a tree that Gaia gave to [[hera]] at her marriage to Zeus, growing in the garden of the Hesperides under the guard of the dragon [[ladon]]. For his eleventh labour [[heracles]] obtained them, either by killing the dragon or by holding up the sky while Atlas fetched them. Athena afterwards returned the apples to the garden. Golden apples also feature in the race of Atalanta and the Judgement of Paris." }),
  a("cornucopia", "Cornucopia", "treasure", "🌽", "The Horn of Plenty", undefined, { aliases: ["Horn of Plenty", "Horn of Amalthea", "Keras Amaltheias"], summary: "A horn that supplied its owner with unlimited food and drink. In one account it was the horn of the goat [[amalthea]], nurse of the infant Zeus, which the god broke off and endowed with its power; in another it was torn from the river god [[achelous]] by Heracles when they wrestled for Deianira. It became the attribute of deities of abundance and fortune such as Tyche, Plutus and Demeter." }),
];

export const stories: EntitySeed[] = [
  s("theogony", "Theogony", "epic", "📜", "Hesiod's Genealogy of the Gods", undefined, { aliases: ["Theogonia", "Birth of the Gods"], summary: "A poem of just over a thousand lines by Hesiod, composed around 700 BC, that sets out the origin of the cosmos and the genealogies of the gods. It moves from Chaos, Gaia and Eros through the reigns of [[uranus]] and [[cronus]] to the victory of [[zeus]] over the Titans and Typhon. It is the earliest systematic account of Greek mythology and the chief source for the succession myth." }),
  s("iliad", "Iliad", "epic", "📕", "Homer's Poem of the Wrath of Achilles", undefined, { aliases: ["Ilias", "Song of Ilium"], summary: "An epic poem in twenty-four books, attributed to Homer and generally dated to the eighth century BC. It covers a few weeks in the tenth year of the [[trojan-war]]: the quarrel between [[achilles]] and Agamemnon, Achilles' withdrawal from battle, the death of Patroclus, the killing of [[hector]] and the ransoming of his body by Priam. The oldest surviving work of Greek literature, it was the foundation of Greek education and the model for all later epic." }),
  s("odyssey", "Odyssey", "epic", "📗", "Homer's Poem of the Return of Odysseus", undefined, { aliases: ["Odysseia"], summary: "An epic poem in twenty-four books attributed to Homer, usually dated slightly later than the Iliad, to the late eighth or early seventh century BC. It follows the ten-year journey of [[odysseus]] home from Troy, the search of his son Telemachus for news of him, and his vengeance on the suitors of [[penelope]]. Much of the adventure is told by the hero himself in flashback at the court of the Phaeacians." }),
  s("homeric-hymns", "Homeric Hymns", "hymns", "🎶", "Hexameter Hymns to the Gods", undefined, { aliases: ["Hymni Homerici"], summary: "A collection of thirty-three anonymous hexameter poems in honour of individual gods, attributed to Homer in antiquity but composed by various hands, mostly between the seventh and fifth centuries BC. The longer hymns, to Demeter, Apollo, Hermes and Aphrodite, are major narrative sources: they tell of the abduction of Persephone, the founding of Delphi, the infant Hermes' theft of Apollo's cattle, and Aphrodite's love for Anchises." }),
  s("argonautica", "Argonautica", "epic", "📘", "Apollonius's Epic of the Argo", undefined, { aliases: ["Argonautika"], summary: "A Greek epic in four books by Apollonius of Rhodes, written at Alexandria in the third century BC. It is the only complete surviving account of the voyage of [[jason]] and the Argonauts to Colchis and back. Its portrayal of the young [[medea]] falling in love is a landmark of ancient psychological narrative and strongly influenced Virgil's Dido." }),
  s("bibliotheca", "Bibliotheca", "handbook", "📚", "The Mythographer's Handbook", undefined, { aliases: ["Library of Apollodorus", "Pseudo-Apollodorus", "The Library"], summary: "A prose compendium of Greek myth from the origin of the gods to the death of Odysseus, arranged by family line. It was traditionally ascribed to Apollodorus of Athens but dates from the first or second century AD, and its author is now called Pseudo-Apollodorus. The end survives only in an epitome. Drawing on early poets and mythographers now lost, it is the most comprehensive ancient handbook of the subject." }),
  s("metamorphoses", "Metamorphoses", "epic", "🦋", "Ovid's Poem of Transformations", undefined, { aliases: ["Metamorphoseon Libri"], summary: "A Latin poem in fifteen books by Ovid, completed around AD 8, weaving some 250 myths of transformation into a continuous narrative from the creation of the world to the deification of Julius Caesar. It contains the best-known versions of many stories, among them Daphne, Narcissus and Echo, Arachne, Pyramus and Thisbe, and Orpheus and Eurydice. It has been the single most influential source of classical myth for later European art and literature." }),
  s("aeneid", "Aeneid", "epic", "🦅", "Virgil's Epic of the Founding of Rome", undefined, { aliases: ["Aeneis"], summary: "A Latin epic in twelve books by Virgil, written between 29 and 19 BC and left unrevised at his death. It follows the Trojan prince [[aeneas]] from the [[fall-of-troy]] through his wanderings, his affair with Dido at Carthage and his descent to the underworld, to the war in Latium that establishes the line from which Rome would spring. Modelled on both Homeric poems, it became the national epic of Rome." }),
  s("oresteia", "Oresteia", "tragedy", "🎭", "Aeschylus's Trilogy of the House of Atreus", undefined, { aliases: ["Oresteia Trilogy"], summary: "A trilogy of tragedies by Aeschylus, first performed at Athens in 458 BC, and the only Greek trilogy to survive complete. In Agamemnon, [[clytemnestra]] murders her husband on his return from Troy; in the Libation Bearers, [[orestes]] kills her in revenge; in the Eumenides, he is pursued by the Erinyes and acquitted at Athens by a court founded by Athena. The cycle traces the replacement of blood vengeance by civic justice." }),
  s("prometheus-bound", "Prometheus Bound", "tragedy", "⛓️", "Tragedy of the Chained Titan", undefined, { aliases: ["Prometheus Desmotes", "Prometheus Vinctus"], summary: "A tragedy traditionally attributed to Aeschylus, though its authorship and date, probably the mid fifth century BC, are disputed. [[prometheus]], chained to a crag at the edge of the world for giving fire to mortals, is visited by the Oceanids, Oceanus, the wandering [[io]] and Hermes, and refuses to reveal the secret that threatens the rule of Zeus. It was the first play of a trilogy whose sequels are lost." }),
  s("oedipus-rex", "Oedipus Rex", "tragedy", "👁️", "Sophocles's Tragedy of Oedipus", undefined, { aliases: ["Oedipus Tyrannus", "Oedipus the King"], summary: "A tragedy by Sophocles, first produced at Athens around 429 BC. Seeking the cause of a plague on Thebes, King [[oedipus]] investigates the murder of his predecessor Laius and discovers that he himself is the killer, that Laius was his father and that his wife [[jocasta]] is his mother. Jocasta hangs herself and Oedipus puts out his own eyes. Aristotle treated it as a model of tragic plot construction." }),
  s("bacchae", "Bacchae", "tragedy", "🍇", "Euripides's Tragedy of Dionysus at Thebes", undefined, { aliases: ["Bakchai", "The Bacchantes"], summary: "A tragedy by Euripides, written in Macedonia near the end of his life and produced posthumously at Athens in 405 BC, when it won first prize. [[dionysus]] returns in disguise to Thebes, his mother's city, to punish it for denying his divinity. He drives the women to the mountains as maenads and lures King [[pentheus]] to spy on them, where he is torn apart by his own mother, Agave." }),
  s("medea-play", "Medea", "tragedy", "🧪", "Euripides's Revenge Tragedy", undefined, { aliases: ["Medeia"], summary: "A tragedy by Euripides, first produced at Athens in 431 BC, where it placed third. At Corinth [[jason]] abandons [[medea]] to marry the daughter of King Creon. Medea sends the bride a poisoned robe and crown that kill both her and her father, then murders her own two sons to complete Jason's ruin and escapes in the chariot of her grandfather Helios. The killing of the children by Medea herself may have been Euripides' innovation." }),
];
